node.doctext:
You cannot create the links before both the source and target directories exist. So, postpone their creation to the end. The directories are processed from the shortest to the longest, so we always know the parent path exists. 
You should also add a check that a link doesn't point outside of the given directory tree.<P>

I created the following Makefile to experiment with your data:
<readmore><c>
SHELL := /bin/bash

.PHONY: test
test: clean prepare
	echo $$'#!/bin/bash\ntarget=top2\nmkdir -p $$target/top' > 1.sh
	./1.pl top >> 1.sh
	chmod u+x 1.sh
	./1.sh
	diff -r top top2/top

.PHONY: prepare
prepare:
	mkdir -p top/usr
	mkdir -p top/root/site/tools/gauv/python3/3.6.3/{lib,bin}
	touch top/root/site/tools/gauv/python3/3.6.3/bin/python3.6
	ln -s $(PWD)/top/root/site/tools/gauv top/usr/vsa
	ln -s 3.6.3 top/root/site/tools/gauv/python3/3.6.3a

.PHONY: clean
clean:
	rm -rf top top2 1.sh
</c></readmore><P>

And this was the script 1.pl:
<c>
#!/usr/bin/perl
use warnings;
use strict;
use feature qw{ say };

use Path::Tiny qw{ path };

my $path = path(shift);
my $paths = $path->visit(
    sub { $_[1]->{$_} = (-f) ? 'file'
                      : (-l) ? [readlink]
                      : (-d) ? 'dir'
                             : 'unknown' },
    { recurse => 1 }
);

my @links;
for my $found (sort { length $a <=> length $b } keys %$paths) {
    if ('file' eq $paths->{$found}) {
        say qq(cp '$found' "\$target/$found");

    } elsif ('dir' eq $paths->{$found}) {
        say qq(mkdir "\$target/$found");

    } elsif (ref [] eq ref $paths->{$found}) {
        my $to = path($paths->{$found}[0]);
        $to = $to->relative(path($found)->absolute->parent)
            if $to->is_absolute;
        my $source = path('$target', $found);
        push @links, qq(ln -s "$to" "$source");
    }
}
say for @links;
</c><P>

It's just a toy. Use some of the ShellQuote modules to fix the filenames; but for the example given, it works.<P>



